import{_ as n,c as s,o as e,ah as a}from"./chunks/framework.DE7iKuik.js";const m=JSON.parse('{"title":"自定义安装器","frontmatter":{"title":"自定义安装器","createTime":"2025/01/17 19:27:31","permalink":"/docs/composer/installers.html","lastUpdated":"2026-01-22","tags":[],"link":"/docs/composer/官方文章/installers","layout":"doc","sidebar":true,"aside":true,"prev":{"text":"自动加载器优化","link":"/docs/composer/官方文章/optimization"},"next":{"text":"使用 Satis 处理私有仓库","link":"/docs/composer/官方文章/private-packages-with-satis"}},"headers":[],"params":{"pkg":"composer/官方文章/installers","sidebar":[{"text":"为什么 Composer 不递归加载代码库？","dir":"常见问题","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively","children":[null,null,null,null,null,null,null,null]},{"text":"为什么 Composer 不递归加载代码库？","dir":"常见问题","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively","children":[null,null,null,null,null,null,null,null]},{"text":"为什么 Composer 不递归加载代码库？","dir":"常见问题","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively","children":[null,null,null,null,null,null,null,null]},{"text":"为什么 Composer 不递归加载代码库？","dir":"常见问题","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively","children":[null,null,null,null,null,null,null,null]},{"text":"为什么 Composer 不递归加载代码库？","dir":"常见问题","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively","children":[null,null,null,null,null,null,null,null]},{"text":"为什么 Composer 不递归加载代码库？","dir":"常见问题","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively","children":[null,null,null,null,null,null,null,null]},{"text":"为什么 Composer 不递归加载代码库？","dir":"常见问题","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively","children":[null,null,null,null,null,null,null,null]},{"text":"为什么 Composer 不递归加载代码库？","dir":"常见问题","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively","children":[null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"社区","dir":"教程","link":"/docs/composer/教程/community","children":[null,null,null,null,null,null,null,null]},{"text":"社区","dir":"教程","link":"/docs/composer/教程/community","children":[null,null,null,null,null,null,null,null]},{"text":"社区","dir":"教程","link":"/docs/composer/教程/community","children":[null,null,null,null,null,null,null,null]},{"text":"社区","dir":"教程","link":"/docs/composer/教程/community","children":[null,null,null,null,null,null,null,null]},{"text":"社区","dir":"教程","link":"/docs/composer/教程/community","children":[null,null,null,null,null,null,null,null]},{"text":"社区","dir":"教程","link":"/docs/composer/教程/community","children":[null,null,null,null,null,null,null,null]},{"text":"社区","dir":"教程","link":"/docs/composer/教程/community","children":[null,null,null,null,null,null,null,null]},{"text":"社区","dir":"教程","link":"/docs/composer/教程/community","children":[null,null,null,null,null,null,null,null]}],"versions":[]},"relativePath":"docs/composer/官方文章/installers.md","filePath":"docs/[pkg].md"}'),p={name:"docs/composer/官方文章/installers.md"};function o(r,l,t,i,c,u){return e(),s("div",null,[...l[0]||(l[0]=[a(`<h1 id="设置和使用自定义安装程序" tabindex="-1">设置和使用自定义安装程序 <a class="header-anchor" href="#设置和使用自定义安装程序" aria-label="Permalink to “设置和使用自定义安装程序”">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to “概述”">​</a></h2><p>有些时候，程序包可能需要在安装期间执行其他操作，例如在程序默认扩展库之外安装其他扩展包。</p><p>在这种情况下，你可以考虑创建自定义安装程序来处理你的特定安装逻辑。</p><h2 id="调用自定义安装程序" tabindex="-1">调用自定义安装程序 <a class="header-anchor" href="#调用自定义安装程序" aria-label="Permalink to “调用自定义安装程序”">​</a></h2><p>假设你的程序已经有特定模块的自定义安装程序，那么调用这个安装程序就需要在扩展包文件中定义正确的安装 <a href="https://github.com/composer/composer/blob/master/doc/04-schema.md#type" target="_blank" rel="noreferrer">类型</a> 。</p><blockquote><p><em>关于如何创建自定义安装程序的说明，请参考下一章节</em></p></blockquote><p>每个自定义安装程序都会定义它识别的安装 <a href="https://learnku.com/docs/composer/2018/04-schema/2085" target="_blank" rel="noreferrer">类型</a> 。 如果执行识别成功，它讲完全覆盖默认的扩展包并执行它自有的逻辑。</p><p>下面是一个实例：</p><blockquote><p>PHP文档中说明该功能需要除了在默认开发者提供的扩展包之外安装扩展，因此，他们会选择并采用 <code>phpdocumentor-template</code> <a href="https://learnku.com/docs/composer/2018/04-schema/2085" target="_blank" rel="noreferrer">类型</a> 并创建一个插件，提供自定义安装程序将这些扩展提交到指定的文件夹里。</p></blockquote><p>下面就有一个 <code>composer.json</code> 模板文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;name&quot;: &quot;phpdocumentor/template-responsive&quot;,</span><span>  //类名称</span></span>
<span class="line"><span>    &quot;type&quot;: &quot;phpdocumentor-template&quot;,</span><span>  //类型</span></span>
<span class="line"><span>    &quot;require&quot;: {</span></span>
<span class="line"><span>        &quot;phpdocumentor/template-installer-plugin&quot;: &quot;*&quot;</span><span>  //扩展包名称及版本号</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><blockquote><p>重要提示： 为了确保安装扩展包时验证模板文件存在，执行模板文件需要安装插件包。</p></blockquote><h2 id="创建安装程序" tabindex="-1">创建安装程序 <a class="header-anchor" href="#创建安装程序" aria-label="Permalink to “创建安装程序”">​</a></h2><p>自定义安装程序定义为实现 <a href="https://github.com/composer/composer/blob/master/src/Composer/Installer/InstallerInterface.php" target="_blank" rel="noreferrer"><code>Composer\\Installer\\InstallerInterface</code></a> 的类，通常分步在 Composer 插件中。</p><p>因此，一个基本的安装程序插件将由三个文件组成：</p><ol><li>包文件：composer.json</li><li>Plugin 类，例如： <code>My\\Project\\Composer\\Plugin.php</code> ，包含一个实现 <code>Composer\\Plugin\\PluginInterface</code> 的类。</li><li>Installer 类，例如： <code>My\\Project\\Composer\\Installer.php</code>，包含实现 <code>Composer\\Installer\\InstallerInterface</code> 的类。</li></ol><h3 id="composer-json" tabindex="-1">composer.json <a class="header-anchor" href="#composer-json" aria-label="Permalink to “composer.json”">​</a></h3><p>包文件与任何其他包文件相同，但具有以下要求：</p><ol><li><a href="https://github.com/composer/composer/blob/master/doc/04-schema.md#type" target="_blank" rel="noreferrer">type</a> 属性必须是 <code>composer-plugin</code> 。</li><li><a href="https://github.com/composer/composer/blob/master/doc/04-schema.md#extra" target="_blank" rel="noreferrer">extra</a> 属性必须包含一个定义插件类名的元素类（包括命名空间）。如果包中包含多个插件，则可以是类名称数组。</li></ol><p>例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;name&quot;: &quot;phpdocumentor/template-installer-plugin&quot;,</span></span>
<span class="line"><span>    &quot;type&quot;: &quot;composer-plugin&quot;,</span></span>
<span class="line"><span>    &quot;license&quot;: &quot;MIT&quot;,</span></span>
<span class="line"><span>    &quot;autoload&quot;: {</span></span>
<span class="line"><span>        &quot;psr-0&quot;: {&quot;phpDocumentor\\\\Composer&quot;: &quot;src/&quot;}</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>    &quot;extra&quot;: {</span></span>
<span class="line"><span>        &quot;class&quot;: &quot;phpDocumentor\\\\Composer\\\\TemplateInstallerPlugin&quot;</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>    &quot;require&quot;: {</span></span>
<span class="line"><span>        &quot;composer-plugin-api&quot;: &quot;^1.0&quot;</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>    &quot;require-dev&quot;: {</span></span>
<span class="line"><span>        &quot;composer/composer&quot;: &quot;^1.3&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>上面的示例在其 require-dev 中有 Composer 本身，例如，它允许您在测试套件中使用 Composer 类。</p><h3 id="插件类" tabindex="-1">插件类 <a class="header-anchor" href="#插件类" aria-label="Permalink to “插件类”">​</a></h3><p>定义 Composer 插件的类必须实现 <a href="https://github.com/composer/composer/blob/master/src/Composer/Plugin/PluginInterface.php" target="_blank" rel="noreferrer"><code>Composer\\Plugin\\PluginInterface</code></a>. 然后，它可以在其 <code>activate()</code> 方法中注册 Custom Installer。.</p><p>该类可以放在任何位置并具有任何名称，只要它是可自动加载的并且与<code>extra.class</code> 包定义中的元素匹配即可。</p><p>例:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;?php</span></span>
<span class="line"><span></span></span>
<span class="line"><span>namespace phpDocumentor\\Composer;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>use Composer\\Composer;</span></span>
<span class="line"><span>use Composer\\IO\\IOInterface;</span></span>
<span class="line"><span>use Composer\\Plugin\\PluginInterface;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>class TemplateInstallerPlugin implements PluginInterface</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    public function activate(Composer $composer, IOInterface $io)</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        $installer = new TemplateInstaller($io, $composer);</span></span>
<span class="line"><span>        $composer-&gt;getInstallationManager()-&gt;addInstaller($installer);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="自定义安装程序类" tabindex="-1">自定义安装程序类 <a class="header-anchor" href="#自定义安装程序类" aria-label="Permalink to “自定义安装程序类”">​</a></h3><p>执行自定义安装的程序类应实现 <a href="https://github.com/composer/composer/blob/master/src/Composer/Installer/InstallerInterface.php" target="_blank" rel="noreferrer"><code>Composer\\Installer\\InstallerInterface</code></a> （或者扩展实现该接口的另一个安装程序）它定义了 <a href="https://github.com/composer/composer/blob/master/doc/04-schema.md#type" target="_blank" rel="noreferrer">type</a> 字符串，因为它将在 <code>supports()</code> 方法中使用此安装程序的包进行识别。</p><blockquote><p>注意：请仔细选择您的 <a href="https://github.com/composer/composer/blob/master/doc/04-schema.md#type" target="_blank" rel="noreferrer">type</a> 名称，建议遵循以下格式：<code>vendor-type</code> 。例如： <code>phpdocumentor-template</code> 。</p></blockquote><p>InstallerInterface 类定义了以下方法（请参阅精确签名源）：</p><ul><li>supports() ，在这里测试传递的 <a href="https://github.com/composer/composer/blob/master/doc/04-schema.md#type" target="_blank" rel="noreferrer">type</a> 是否与您为此安装程序声明的名称匹配（请参阅示例）。</li><li>isInstalled() ，确定是否安装了受支持的软件包。</li><li>install()，在这里您可以确认安装时需要执行的操作。</li><li>update()，在这里定义使用 update 参数调用 Composer 时所需的行为。</li><li>uninstall()，在这里您可以确定需要移除包时需要执行的操作。</li><li>getInstallPath()，这个方法应该返回要安装的包的位置，<em>相对于 composer.json 的位置</em>。</li></ul><p>例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;?php</span></span>
<span class="line"><span></span></span>
<span class="line"><span>namespace phpDocumentor\\Composer;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>use Composer\\Package\\PackageInterface;</span></span>
<span class="line"><span>use Composer\\Installer\\LibraryInstaller;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>class TemplateInstaller extends LibraryInstaller</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    /**</span></span>
<span class="line"><span>     * {@inheritDoc}</span></span>
<span class="line"><span>     */</span></span>
<span class="line"><span>    public function getInstallPath(PackageInterface $package)</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        $prefix = substr($package-&gt;getPrettyName(), 0, 23);</span></span>
<span class="line"><span>        if (&#39;phpdocumentor/template-&#39; !== $prefix) {</span></span>
<span class="line"><span>            throw new \\InvalidArgumentException(</span></span>
<span class="line"><span>                &#39;Unable to install template, phpdocumentor templates &#39;</span></span>
<span class="line"><span>                .&#39;should always start their package name with &#39;</span></span>
<span class="line"><span>                .&#39;&quot;phpdocumentor/template-&quot;&#39;</span></span>
<span class="line"><span>            );</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        return &#39;data/templates/&#39;.substr($package-&gt;getPrettyName(), 23);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    /**</span></span>
<span class="line"><span>     * {@inheritDoc}</span></span>
<span class="line"><span>     */</span></span>
<span class="line"><span>    public function supports($packageType)</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        return &#39;phpdocumentor-template&#39; === $packageType;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>该示例演示了扩展 <a href="https://github.com/composer/composer/blob/master/src/Composer/Installer/LibraryInstaller.php" target="_blank" rel="noreferrer"><code>Composer\\Installer\\LibraryInstaller</code></a> 类去除前缀（<code>phpdocumentor/template-</code>）并使用剩下部分来组装完全不同的安装路径是非常简单的。</p><blockquote><p><em>而不是安装在 <code>/vendor</code> 中，任何使用此安装程序的程序包都将被放在 <code>/data/templates/&lt;stripped name&gt;</code> 文件夹中</em>。</p></blockquote>`,37)])])}const h=n(p,[["render",o]]);export{m as __pageData,h as default};
